// Jira Cloud stores description as Atlassian Document Format (ADF).
// This extracts plain text from it so the AI prompt gets clean text.
function extractText(node) {
  if (!node) return '';
  if (typeof node === 'string') return node;
  let text = '';
  if (node.type === 'text') {
    text += node.text || '';
  }
  if (Array.isArray(node.content)) {
    for (const child of node.content) {
      text += extractText(child) + ' ';
    }
  }
  return text;
}

// New: escapes newlines/quotes/backslashes so this text is safe to drop into JSON later
function sanitize(str) {
  if (!str) return '';
  return str
    .replace(/\\/g, '\\\\')
    .replace(/\r?\n/g, '\\n')
    .replace(/"/g, '\\"');
}

const fields = $input.first().json.fields;
const summary = sanitize(fields.summary || '');
const description = sanitize(extractText(fields.description).trim() || '(no description provided)');
const ticketKey = $input.first().json.key;

return [{ json: { ticketKey, summary, description } }];

